#!/usr/bin/env python3
"""Generates the RLX settings icons: three sliders, outlined like the Morphe settings icons.

- The entry of the RLX settings in the YouTube settings: vertical sliders, in place of the Morphe icon
  (morphe_settings_icon_*, light and dark theme, regular and bold), written by the RLX core.
- The RLX Customizations screen: horizontal sliders (rlx_settings_screen_customizations*).

usage: settings_icons.py <repository>
"""

import os
import sys

HEADER = """<?xml version="1.0" encoding="utf-8"?>
<!-- RLX Patches: {what}. Generated by rlx/branding/settings_icons.py, do not edit. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="24dp"
    android:height="24dp"
    android:viewportWidth="24"
    android:viewportHeight="24">
"""

# Track ends, knob positions along the track (first, second, third slider) and the track positions.
TRACK_START, TRACK_END = 3.5, 20.5
KNOBS = (8.5, 15.5, 8.5)
TRACKS = (6, 12, 18)

# Stroke width and knob radius.
REGULAR = (1.0, 2.5)
BOLD = (2.0, 3.0)


def f(value):
    return f"{value:g}"


def paths(vertical, stroke, radius):
    """Track segments (round caps) and knob circles, as path data of (x, y) along/across."""
    d = []
    for across, along in zip(TRACKS, KNOBS):
        def point(position):
            return f"{f(across)},{f(position)}" if vertical else f"{f(position)},{f(across)}"

        for start, end in ((TRACK_START, along - radius), (along + radius, TRACK_END)):
            d.append(f"M{point(start)}L{point(end)}")
        cx, cy = (across, along) if vertical else (along, across)
        d.append(
            f"M{f(cx - radius)},{f(cy)}"
            f"A{f(radius)},{f(radius)} 0 1 1 {f(cx + radius)},{f(cy)}"
            f"A{f(radius)},{f(radius)} 0 1 1 {f(cx - radius)},{f(cy)}Z"
        )
    return "".join(d)


def vector(what, vertical, weight, color):
    stroke, radius = weight
    return HEADER.format(what=what) + f"""
    <path
        android:fillColor="@android:color/transparent"
        android:strokeColor="{color}"
        android:strokeWidth="{f(stroke)}"
        android:strokeLineCap="round"
        android:strokeLineJoin="round"
        android:pathData="{paths(vertical, stroke, radius)}" />
</vector>
"""


def write(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(content)


def main(repo):
    resources = os.path.join(repo, "patches/src/main/resources/rlx")

    entry = "icon of the RLX settings entry"
    for theme, color in (("light", "@color/yt_black0"), ("dark", "@color/yt_white1")):
        write(f"{resources}/settings/drawable/morphe_settings_icon_{theme}.xml",
              vector(entry, True, REGULAR, color))
        write(f"{resources}/settings/drawable/morphe_settings_icon_bold_{theme}.xml",
              vector(entry, True, BOLD, color))

    screen = "icon of the RLX Customizations settings screen"
    write(f"{resources}/drawable/rlx_settings_screen_customizations.xml",
          vector(screen, False, REGULAR, "?android:attr/textColorPrimary"))
    write(f"{resources}/drawable/rlx_settings_screen_customizations_bold.xml",
          vector(screen, False, BOLD, "?android:attr/textColorPrimary"))


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    main(sys.argv[1])
